WITH valid_inventory AS (SELECT * FROM inventory WHERE NOT (product_id IN (4, 5, 6, 9) AND last_restock BETWEEN '2023-07-01' AND '2024-12-03')), inventory_stats AS (SELECT store_id, product_id, SUM(quantity) AS total_quantity, MIN(quantity) AS min_quantity FROM valid_inventory GROUP BY store_id, product_id) SELECT store_id, product_id, total_quantity, min_quantity FROM inventory_stats WHERE min_quantity > 160 ORDER BY total_quantity ASC, 4 DESC, store_id ASC, product_id ASC LIMIT 3;
